var t=`0886-rice-and-curry`;var n=`world-0886`;var r=`LK`;var a=`south-asia`;var s=4;var o=76;var d={en:`Rice and Curry`,ua:`Рис із карі`};var u={en:`Rice and Curry is a Sri Lanka dish made with red rice, yellow onion, ginger-garlic paste, fresh curry leaves. This home-scale recipe assigns measured ingredients to the steps where they are used. Includes a quick grated coconut topping rather than separately prepared pol sambol.`,ua:`Рис із карі, страва кухні країни Шрі-Ланка. Основні складники: червоний рис, жовта цибуля, імбирно-часникова паста, свіже листя карі. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів. Додається швидка кокосова присипка замість окремо приготованого пол самболу.`};var l=[{en:`Spread the rice evenly into the flavorful liquid. Cook uncovered or partly covered for about 25 minutes until the liquid is absorbed; do not over-stir.`,ua:`Рівномірно розподіліть рис у ароматній рідині. Готуйте приблизно 25 хвилин до вбирання рідини, не перемішуючи надмірно.`,t:[`rice-washing`,`absorption-cooking`],m:25,i:[[`red-rice`,420,`g`],[`water`,850,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 9 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 9 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:9,i:[[`yellow-onion`,170,`g`],[`ginger-garlic-paste`,22,`g`],[`fresh-curry-leaves`,10,`leaf`],[`coconut-oil`,45,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 30 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 30 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:30,i:[[`chicken-thigh`,640,`g`],[`coconut-milk`,420,`ml`],[`tomato`,250,`g`],[`curry-powder`,13,`g`],[`table-salt`,null,`to_taste`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 9 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 9 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:9,i:[[`green-beans`,240,`g`],[`mustard-seeds`,5,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`desiccated-coconut`,75,`g`],[`red-onion`,50,`g`],[`lime-juice`,25,`ml`]]}];var g={slug:t,id:n,country:`LK`,region:a,servings:4,minutes:76,title:d,text:u,steps:l};export{r as country,g as default,n as id,o as minutes,a as region,s as servings,t as slug,l as steps,u as text,d as title};